/* Spring school-life romance: quiet ink, warm paper and a restrained sakura accent. */
.screen { position:relative; width:100%; height:100%; color:#292d36; }
.screen-dimmer { position:absolute; left:0; top:0; width:100%; height:100%; background-color:rgba(25,34,48,0.36); z-index:1; }

/* Main title: let the illustration carry the scene; the menu is a translucent page. */
.title-screen { position:relative; width:100%; height:100%; color:#fffdf8; }
.title-shade { position:absolute; left:0; top:0; width:440px; height:100%; background-color:rgba(28,39,57,0.78); z-index:1; }
.title-brand { position:absolute; left:48px; top:54px; width:360px; height:94px; z-index:2; }
.title-brand-caption { position:absolute; left:2px; top:0; width:350px; height:22px; color:#f2c6d1; font-size:14px; }
.title-brand-main { position:absolute; left:0; top:26px; width:360px; height:58px; color:#fffaf4; font-size:36px; }
.title-menu { position:absolute; left:28px; top:174px; width:382px; height:430px; display:flex; flex-direction:column; gap:10px; z-index:2; }
.title-item { position:relative; width:100%; height:58px; color:#51434b; background-color:rgba(250,223,230,0.12); background-image:url("asset/ui/choice-romance.png"); background-size:100% 100%; border:1px solid rgba(255,245,236,0.16); text-align:left; }
.title-item:hover { color:#733e53; background-color:rgba(228,152,174,0.34); border-color:#f3d6d8; }
#title-start { color:#713b50; background-color:rgba(232,170,187,0.3); border-color:rgba(245,207,214,0.75); }
#title-start:hover { background-color:rgba(225,139,165,0.46); }
.title-copy { position:absolute; left:54px; top:3px; width:306px; height:50px; display:flex; flex-direction:column; justify-content:center; }
.title-main { color:#51434b; font-size:23px; }
.title-footer { position:absolute; left:50px; bottom:18px; width:340px; height:20px; color:#e7d8d4; font-size:11px; z-index:2; }
.title-footer-left { position:absolute; left:0; top:0; width:190px; height:20px; }
.title-footer-right { position:absolute; right:0; top:0; width:145px; height:20px; text-align:right; }

/* Shared title and navigation for in-world menu pages. */
.screen-header { position:absolute; left:0; top:0; width:100%; height:108px; z-index:4; background-color:rgba(250,246,237,0.91); }
.screen-title { position:absolute; left:44px; top:20px; width:450px; height:62px; color:#303b50; font-size:42px; }
.sound-title { font-size:40px; }
.screen-tabs { position:absolute; right:34px; top:25px; width:510px; height:54px; display:grid; grid-template-columns:repeat(4,1fr); gap:8px; }
.tab-button { position:relative; width:100%; height:50px; color:#46556d; background-color:rgba(255,255,255,0.58); border:1px solid #b8b5ae; }
.tab-button:hover { color:#7c3d55; background-color:#fffaf2; border-color:#bd788c; }
.tab-active { color:#7b4055; background-color:#f3dfe1; border-color:#cb9ba6; }
.tab-glyph { position:absolute; left:0; top:3px; width:100%; height:28px; color:#8d5367; font-size:19px; text-align:center; }
.tab-label { position:absolute; left:0; top:31px; width:100%; height:16px; color:#48536a; font-size:10px; text-align:center; }

/* The page surface is deliberately soft and quiet, like a school notebook. */
.slot-pages { position:absolute; left:40px; top:128px; width:1px; height:1px; display:none; }
.slot-page { color:#364156; background-color:#f8f2e8; border:1px solid #c7bdb0; text-align:center; font-size:16px; }
.slot-page-active { color:#7b4055; background-color:#f1dfe1; border-color:#bd8794; }
.save-slot-grid { position:absolute; left:42px; top:132px; width:1196px; height:500px; display:grid; grid-template-columns:repeat(3,1fr); grid-auto-rows:118px; gap:14px; z-index:3; }
.save-slot { position:relative; width:100%; height:100%; padding:12px; color:#3d4655; background-color:rgba(250,246,237,0.93); border:1px solid #c7bcae; font-size:15px; text-align:left; }
.slot-thumbnail { position:absolute; left:10px; top:12px; width:125px; height:72px; object-fit:cover; }
.slot-thumbnail:not([src]) { display:none; }
.save-slot:hover { color:#67374b; background-color:#fffaf2; border-color:#b8768b; }
.save-slot[data-state="corrupt"],.save-slot[data-state="incompatible"] { border-color:#aa7777; }
.slot-number { position:absolute; left:145px; top:13px; width:42px; height:30px; color:#9b6678; font-size:24px; }
.slot-scene { position:absolute; left:192px; top:14px; width:195px; height:22px; color:#374457; font-size:16px; }
.slot-text { position:absolute; left:145px; top:44px; width:235px; height:26px; color:#525b66; font-size:13px; }
.slot-date { position:absolute; left:145px; top:80px; width:200px; height:17px; color:#78736e; font-size:11px; }
.slot-status { position:absolute; right:15px; top:79px; width:72px; height:18px; color:#9b6678; text-align:right; font-size:11px; }
.quick-panel { position:absolute; left:0; top:0; width:1px; height:1px; color:#3f495a; background-color:transparent; border:0px solid #c8bdae; z-index:3; }
.quick-title,.quick-empty,.quick-copy,.quick-separator,.quick-hint { display:none; }
.data-footer { position:absolute; left:42px; bottom:18px; width:1196px; height:46px; z-index:4; }
.data-hint { position:absolute; left:0; top:13px; width:600px; height:23px; color:#f8f1e8; font-size:13px; }
.footer-button { position:absolute; top:1px; width:148px; height:42px; color:#43516a; background-color:rgba(250,246,237,0.94); border:1px solid #c9bdae; font-size:14px; text-align:center; }
.footer-button:hover { color:#fffaf2; background-color:#875267; border-color:#f1d8dc; }
.data-back { left:900px; width:145px; }
.data-title { left:1052px; width:90px; }
.data-quit { left:1148px; width:90px; }

/* Keep only controls that really work in both players. */
.settings-screen,.sound-screen,.data-screen { color:#303744; }
.system-options { position:absolute; left:130px; top:190px; width:1020px; height:400px; z-index:3; background-color:rgba(250,246,237,0.94); border:1px solid #c8bdae; }
.setting-row { position:absolute; left:40px; top:52px; width:940px; height:68px; color:#384253; }
.setting-label { position:absolute; left:0; top:0; width:390px; height:48px; color:#344158; font-size:19px; }
.setting-help { position:absolute; left:0; top:27px; width:380px; height:24px; color:#77736f; font-size:13px; }
.option-pair { position:absolute; left:400px; top:2px; width:500px; height:48px; display:grid; grid-template-columns:repeat(2,1fr); gap:10px; }
.option-two { grid-template-columns:repeat(2,1fr); }
.option-three { grid-template-columns:repeat(3,1fr); }
.option { color:#475064; background-color:#eee8df; border:1px solid #c9c0b5; text-align:center; font-size:14px; }
.option-selected { color:#fffaf5; background-color:#718096; border-color:#718096; }
.setting-slider { position:absolute; left:400px; top:15px; width:500px; height:12px; background-color:#d4cbbf; border:1px solid #aaa092; }
.setting-slider-fill { position:absolute; left:0; top:0; height:100%; background-color:#b57589; }
.setting-thumb { position:absolute; top:-11px; width:30px; height:30px; color:#78475a; font-size:23px; }
.fill-65 { width:65%; }.fill-45 { width:45%; }.fill-25 { width:25%; }.fill-55 { width:55%; }.fill-80 { width:80%; }.fill-90 { width:90%; }
.range-min { position:absolute; left:400px; top:31px; width:45px; height:16px; color:#817a72; font-size:9px; }
.range-max { position:absolute; left:855px; top:31px; width:45px; height:16px; color:#817a72; font-size:9px; text-align:right; }
.shortcut-options { position:absolute; left:0; top:0; width:1px; height:1px; display:none; }
.setting-section-title,.shortcut-grid,.click-section-title,.mouse-grid { display:none; }
.settings-footer { position:absolute; left:30px; bottom:12px; width:1220px; height:48px; z-index:4; }
.settings-back { left:0; width:175px; }
.settings-game { left:744px; width:165px; }
.settings-title { left:925px; width:165px; }
.settings-quit { left:1105px; width:115px; }

/* Audio and dialogue controls: one readable paper panel, no fake character meters. */
.volume-panel { position:absolute; left:118px; top:148px; width:1044px; height:486px; color:#374154; z-index:3; background-color:rgba(250,246,237,0.95); border:1px solid #c8bdae; }
.volume-row { position:absolute; left:56px; width:910px; height:54px; }
.volume-row-0 { top:44px; }.volume-row-1 { top:112px; }.volume-row-2 { top:180px; }.volume-row-3 { top:0; display:none; }.volume-row-4 { top:248px; }.volume-row-5 { top:0; display:none; }
.volume-name { position:absolute; left:0; top:0; width:330px; height:27px; color:#38445a; font-size:17px; }
.mute-box { position:absolute; right:4px; top:2px; width:82px; height:20px; color:#626873; font-size:10px; text-align:right; }
.volume-track,.voice-track,.voice-mute,.voice-test,.sound-toggle-title,.sound-toggle-row,.sound-note { display:none; }
.audio-control { position:absolute; left:56px; width:910px; height:20px; accent-color:#a46a7c; z-index:5; }
.audio-master { top:94px; }.audio-bgm { top:162px; }.audio-se { top:230px; }.audio-voice { top:298px; }
.audio-mute { position:absolute; left:400px; width:18px; height:18px; accent-color:#a46a7c; z-index:6; }
.audio-bgm-mute { top:113px; }.audio-se-mute { top:181px; }.audio-voice-mute { top:249px; }
.audio-mute-label { position:absolute; left:423px; width:72px; height:18px; color:#746b69; font-size:11px; z-index:6; }
.audio-bgm-mute-label { top:113px; }.audio-se-mute-label { top:181px; }.audio-voice-mute-label { top:249px; }
.dialog-opacity-label { position:absolute; left:56px; top:354px; width:430px; height:24px; color:#38445a; font-size:17px; }
.dialog-opacity-control { top:390px; }
.voice-grid { position:absolute; left:0; top:0; width:1px; height:1px; display:none; }
.voice-card,.voice-card-shade,.voice-test,.voice-mute,.voice-name,.voice-track { display:none; }
.sound-footer { position:absolute; left:30px; bottom:12px; width:1220px; height:48px; z-index:4; }

/* Pause panel and secondary story pages. */
.pause-screen { position:relative; width:100%; height:100%; color:#303744; }
.pause-dimmer { position:absolute; left:0; top:0; width:100%; height:100%; background-color:rgba(25,34,48,0.38); z-index:1; }
.pause-panel { position:absolute; right:28px; top:18px; width:352px; height:674px; background-color:rgba(250,246,237,0.96); border:1px solid #c8bdae; z-index:3; }
.pause-heading { position:absolute; left:22px; top:20px; width:308px; height:42px; color:#354158; text-align:center; font-size:27px; }
.pause-rule { position:absolute; left:26px; top:66px; width:300px; height:2px; background-color:#b87c8d; }
.pause-grid { position:absolute; left:22px; top:91px; width:308px; height:430px; display:grid; grid-template-columns:repeat(2,1fr); grid-auto-rows:52px; gap:8px; }
.pause-button { width:100%; height:52px; color:#4a566b; background-color:#f6f0e7; border:1px solid #c8bdae; text-align:center; font-size:14px; }
.pause-button:hover { color:#fffaf2; background-color:#875267; border-color:#dcb2bc; }
.pause-unavailable { color:#9a968f; background-color:#eee9e1; opacity:0.48; }
.pause-volume-label { position:absolute; left:24px; top:548px; width:280px; height:22px; color:#465168; font-size:14px; }
.pause-volume-track { position:absolute; left:28px; top:582px; width:292px; height:10px; background-color:#d4cbbf; border:1px solid #aaa092; }
.pause-volume-fill { position:absolute; left:0; top:0; width:66%; height:100%; background-color:#b57589; }
.pause-volume-thumb { position:absolute; left:62%; top:-12px; width:30px; height:30px; color:#78475a; font-size:23px; }
.pause-volume-min { position:absolute; left:25px; top:600px; width:60px; height:16px; color:#817a72; font-size:9px; }
.pause-volume-max { position:absolute; right:25px; top:600px; width:60px; height:16px; color:#817a72; font-size:9px; text-align:right; }
.extra-screen { position:relative; width:100%; height:100%; color:#303744; }
.extra-card { position:absolute; left:300px; top:150px; width:680px; height:420px; background-color:rgba(250,246,237,0.96); border:1px solid #c8bdae; z-index:3; }
.extra-kicker { position:absolute; left:42px; top:42px; width:580px; height:24px; color:#8d5367; font-size:14px; }
.extra-heading { position:absolute; left:42px; top:84px; width:580px; height:74px; color:#354158; font-size:48px; }
.extra-copy { position:absolute; left:46px; top:180px; width:560px; height:90px; color:#626873; font-size:18px; }
.extra-back { position:absolute; left:42px; bottom:32px; width:230px; height:50px; color:#fffaf2; background-color:#718096; border:1px solid #59667b; font-size:16px; }
.extra-back:hover { color:#ffffff; background-color:#875267; }
.about-screen,.guide-screen { position:relative; width:100%; height:100%; color:#303744; }
.center-card { position:absolute; left:220px; top:150px; width:840px; height:420px; padding:36px; background-color:rgba(250,246,237,0.96); border:1px solid #c8bdae; z-index:3; }
.screen-heading { position:absolute; left:44px; top:44px; width:740px; height:70px; color:#354158; font-size:38px; }
.screen-subtitle { position:absolute; left:48px; top:142px; width:740px; height:130px; color:#5e626a; font-size:19px; }
.card-back { position:absolute; left:44px; bottom:32px; width:220px; height:48px; color:#fffaf2; background-color:#718096; border:1px solid #59667b; font-size:16px; }
.card-back:hover { background-color:#875267; }

